CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username varchar(80) UNIQUE NOT NULL, email varchar(255) UNIQUE NOT NULL, name varchar(160) NOT NULL, password_hash text NOT NULL, role varchar(20) NOT NULL DEFAULT 'USER' CHECK(role IN('ADMIN','USER')), active boolean NOT NULL DEFAULT true, theme varchar(20) NOT NULL DEFAULT 'system', currency char(3) NOT NULL DEFAULT 'EUR', locale varchar(20) NOT NULL DEFAULT 'de-DE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS password_reset_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(sid varchar NOT NULL COLLATE "default" PRIMARY KEY, sess json NOT NULL, expire timestamp(6) NOT NULL); CREATE INDEX IF NOT EXISTS idx_sessions_expire ON sessions(expire);
CREATE TABLE IF NOT EXISTS accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name varchar(120) NOT NULL, type varchar(40) NOT NULL, description text, opening_balance numeric(14,2) NOT NULL DEFAULT 0, currency char(3) NOT NULL DEFAULT 'EUR', color varchar(20), icon varchar(60), archived boolean NOT NULL DEFAULT false, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name varchar(120) NOT NULL, kind varchar(20) NOT NULL CHECK(kind IN('income','expense','both')), color varchar(20), icon varchar(60), archived boolean NOT NULL DEFAULT false, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), UNIQUE(user_id,name,kind));
CREATE TABLE IF NOT EXISTS customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name varchar(160) NOT NULL, company varchar(160), address text, email varchar(255), phone varchar(80), customer_no varchar(80), tax_info text, notes text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name varchar(160) NOT NULL, company varchar(160), address text, email varchar(255), phone varchar(80), supplier_no varchar(80), tax_info text, notes text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name varchar(160) NOT NULL, description text, archived boolean DEFAULT false, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, type varchar(20) NOT NULL CHECK(type IN('income','expense')), tx_date date NOT NULL, description text NOT NULL, merchant varchar(180), net_amount numeric(14,2) NOT NULL CHECK(net_amount>=0), tax_amount numeric(14,2) NOT NULL DEFAULT 0 CHECK(tax_amount>=0), gross_amount numeric(14,2) NOT NULL CHECK(gross_amount>=0), account_id uuid REFERENCES accounts(id), category_id uuid REFERENCES categories(id), customer_id uuid REFERENCES customers(id), supplier_id uuid REFERENCES suppliers(id), project_id uuid REFERENCES projects(id), scope varchar(20) NOT NULL DEFAULT 'private' CHECK(scope IN('private','business')), tax_relevant boolean NOT NULL DEFAULT false, status varchar(30) NOT NULL DEFAULT 'paid', payment_date date, payment_method varchar(80), invoice_number varchar(100), reference varchar(160), notes text, archived boolean NOT NULL DEFAULT false, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_tx_user_date ON transactions(user_id,tx_date DESC); CREATE INDEX IF NOT EXISTS idx_tx_filter ON transactions(user_id,type,scope,status); CREATE INDEX IF NOT EXISTS idx_tx_cat ON transactions(category_id); CREATE INDEX IF NOT EXISTS idx_tx_account ON transactions(account_id);
CREATE TABLE IF NOT EXISTS tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name varchar(80) NOT NULL, UNIQUE(user_id,name));
CREATE TABLE IF NOT EXISTS transaction_tags(transaction_id uuid REFERENCES transactions(id) ON DELETE CASCADE, tag_id uuid REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(transaction_id,tag_id));
CREATE TABLE IF NOT EXISTS invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, invoice_number varchar(100) NOT NULL, customer_id uuid REFERENCES customers(id), invoice_date date NOT NULL, due_date date, status varchar(20) NOT NULL DEFAULT 'draft' CHECK(status IN('draft','open','paid','overdue','cancelled')), net_amount numeric(14,2) NOT NULL DEFAULT 0, tax_amount numeric(14,2) NOT NULL DEFAULT 0, gross_amount numeric(14,2) NOT NULL DEFAULT 0, payment_date date, notes text, transaction_id uuid REFERENCES transactions(id) ON DELETE SET NULL, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), UNIQUE(user_id,invoice_number));
CREATE TABLE IF NOT EXISTS invoice_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, description text NOT NULL, quantity numeric(12,3) NOT NULL DEFAULT 1, unit_price numeric(14,2) NOT NULL, tax_rate numeric(6,3) NOT NULL DEFAULT 0, position int NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, transaction_id uuid REFERENCES transactions(id) ON DELETE SET NULL, original_name text NOT NULL, stored_name text NOT NULL UNIQUE, mime_type varchar(100) NOT NULL, size_bytes bigint NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS budgets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, category_id uuid REFERENCES categories(id), amount numeric(14,2) NOT NULL, period varchar(20) NOT NULL DEFAULT 'monthly', active boolean DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS recurring_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, type varchar(20) NOT NULL CHECK(type IN('income','expense')), description text NOT NULL, amount numeric(14,2) NOT NULL, frequency varchar(30) NOT NULL, next_date date NOT NULL, account_id uuid REFERENCES accounts(id), category_id uuid REFERENCES categories(id), active boolean DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS tax_settings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, reserve_percent numeric(5,2) NOT NULL DEFAULT 30 CHECK(reserve_percent BETWEEN 0 AND 100), default_tax_rate numeric(5,2) NOT NULL DEFAULT 19, updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS dashboard_layouts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, layout jsonb NOT NULL DEFAULT '[]', updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS dashboard_widgets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, widget_key varchar(80) NOT NULL, settings jsonb DEFAULT '{}', visible boolean DEFAULT true, UNIQUE(user_id,widget_key));
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY, user_id uuid REFERENCES users(id) ON DELETE SET NULL, action varchar(80) NOT NULL, entity_type varchar(80), entity_id text, changes jsonb, ip inet, created_at timestamptz DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_audit_user_time ON audit_logs(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS imports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, filename text NOT NULL, status varchar(30) NOT NULL, report jsonb DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS import_rows(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), import_id uuid NOT NULL REFERENCES imports(id) ON DELETE CASCADE, row_no int NOT NULL, raw_data jsonb NOT NULL, status varchar(30), duplicate_of uuid REFERENCES transactions(id));
CREATE TABLE IF NOT EXISTS settings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, key varchar(120) NOT NULL, value jsonb NOT NULL, UNIQUE(user_id,key));
